 if(side){p([[7,-60],[9,-59],[9,-56],[11,-54],[10,-51],[8,-50],[6,-47],[1,-47],[-2,-50]],H.ink);p([[-2,-62],[5,-62],[7,-59],[7,-55],[9,-53],[7,-52],[5,-49],[1,-49],[-2,-52]],H.skin);p([[3,-61],[6,-60],[6,-55],[9,-53],[6,-52],[5,-50],[2,-50]],H.skinHi);r(5,-58,1.5,2.5,H.ink);r(6,-51,2,.5,H.skinDeep);r(-1,-56,3,4,H.skinLo);r(0,-56,2,2,H.skin);if(sideburn)r(-3,-61,2,6,sideburn);}
