 B:[[-12,-53],[-14,-57],[-14.5,-63],[-13.5,-68],[-11,-72.5],[-7,-76],[-2,-77.5],[3,-77],[7.5,-75.5],[11,-72],[13,-68],[13.5,-63],[13,-57],[11,-53],[6,-51],[-6,-51]],
