// Inset a closed outline toward its centroid by roughly one world pixel.
const inset=(pts,d=1)=>{const cx=pts.reduce((s,v)=>s+v[0],0)/pts.length,cy=pts.reduce((s,v)=>s+v[1],0)/pts.length;return pts.map(([x,y])=>{const l=Math.hypot(x-cx,y-cy)||1;return [x-(x-cx)/l*d,y-(y-cy)/l*d];});};
